// unit-test.lib.civet

type AutoPromise<T> = Promise<Awaited<T>>;
import {doesNotThrow} from "node:assert"
import {assert, assertEquals, assertThrows} from '@std/assert'

import {unify} from 'unify'
import {
	undef, sleep, defined, notdefined,
	} from 'base-utils'
import {justThrow, croak, getMyOutsideCaller} from 'croak'
import {TIterator, TAsyncIterator, TVoidFunc, hash} from 'datatypes'

let nextNum = 1

// ---------------------------------------------------------------------------

const getTestName = (): string => {

	const n = nextNum
	nextNum += 1
	const frame = getMyOutsideCaller()
	return `${n}. ` + (defined(frame) ? `line ${frame.line}` : "line ?")
}

// ---------------------------------------------------------------------------

export const equal = (
		value: unknown,
		expected: unknown,
		name?: string
		): void => {

	Deno.test(name || getTestName(), () => assertEquals(value, expected))
	return
}

// ---------------------------------------------------------------------------

export const truthy = (
		value: unknown,
		name?: string
		): void => {

	Deno.test(name || getTestName(), () => assert(value))
	return
}

// ---------------------------------------------------------------------------

export const falsy = (
		value: unknown,
		name?: string
		): void => {

	Deno.test(name || getTestName(), () => assert((!value)))
	return
}

// ---------------------------------------------------------------------------

export const succeeds = (
	func: TVoidFunc,
	name?: string
	): void => {

	Deno.test(name || getTestName(), async (): AutoPromise<void> => {
		await func()
	})
	return
}

// ---------------------------------------------------------------------------

export const fails = (
	func: TVoidFunc,
	name?: string
	): void => {

	Deno.test(name || getTestName(), (): void => {
		justThrow(true)
		try {
			func()
			croak("in fails() but function succeeded")
		}
		catch (err) {}
		finally {
			justThrow(false)
		}
	})
	return
}

// ---------------------------------------------------------------------------
// ASYNC

export const generates = <TOut,>(
		value: TIterator<TOut>,
		expected: unknown,
		name?: string
		): void => {

	const lItems = [...value]
	Deno.test(name || getTestName(), () => assertEquals(lItems, expected))
	return
}

// ---------------------------------------------------------------------------
// ASYNC

export const generatesAsync = async <TOut,>(
		value: TAsyncIterator<TOut>,
		expected: unknown,
		name?: string
		): AutoPromise<void> => {

	const lItems = await Array.fromAsync(value)
	Deno.test(name || getTestName(), () => assertEquals(lItems, expected))
	return
}

// ---------------------------------------------------------------------------

export const unifies = (
		value: unknown,
		expected: unknown,
		name?: string
		): void => {

	Deno.test(name || getTestName(), (): void => {
		unify(value, expected)
	})
//	succeeds () => unify value, expected
	return
}

